import{_ as r,I as c,c as n,o as t,a3 as a,b as d,w as o,a as l,J as s,a4 as g}from"./chunks/framework.MI-M1z4O.js";const x=JSON.parse(`{"title":"SyncWatch Architecture — 8 Global Threat Feed Collection, 5-Stage SSRF Guard, and Dual Rule Compiler","description":"Explains SyncWatch's collection channels for 8 global threat feeds (OSV.dev, GitHub GHSA, NVD CVE, CISA KEV, Nuclei, OWASP CRS, MITRE ATT&CK, KISA), 5-stage SSRF defense guard, WatchRuleCompilerService dual security rule compilation, and self-sandbox verification architecture.","frontmatter":{"title":"SyncWatch Architecture — 8 Global Threat Feed Collection, 5-Stage SSRF Guard, and Dual Rule Compiler","description":"Explains SyncWatch's collection channels for 8 global threat feeds (OSV.dev, GitHub GHSA, NVD CVE, CISA KEV, Nuclei, OWASP CRS, MITRE ATT&CK, KISA), 5-stage SSRF defense guard, WatchRuleCompilerService dual security rule compilation, and self-sandbox verification architecture.","sidebarTitle":"Architecture & Rule Compiler","sort":2,"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/syncwatch/architecture"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncwatch/architecture"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncwatch/architecture"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncwatch/architecture"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncwatch/architecture"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncWatch Architecture — 8 Global Threat Feed Collection, 5-Stage SSRF Guard, and Dual Rule Compiler | Empasy Docs"}],["meta",{"property":"og:description","content":"Explains SyncWatch's collection channels for 8 global threat feeds (OSV.dev, GitHub GHSA, NVD CVE, CISA KEV, Nuclei, OWASP CRS, MITRE ATT&CK, KISA), 5-stage SSRF defense guard, WatchRuleCompilerService dual security rule compilation, and self-sandbox verification architecture."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/syncwatch/architecture"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncWatch Architecture — 8 Global Threat Feed Collection, 5-Stage SSRF Guard, and Dual Rule Compiler | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Explains SyncWatch's collection channels for 8 global threat feeds (OSV.dev, GitHub GHSA, NVD CVE, CISA KEV, Nuclei, OWASP CRS, MITRE ATT&CK, KISA), 5-stage SSRF defense guard, WatchRuleCompilerService dual security rule compilation, and self-sandbox verification architecture."}]]},"headers":[],"relativePath":"en/syncwatch/architecture.md","filePath":"en/syncwatch/architecture.md","lastUpdated":1795293539000}`),h={name:"en/syncwatch/architecture.md"};function p(u,e,S,m,f,y){const i=c("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="syncwatch-system-architecture-and-dual-rule-compiler" tabindex="-1">SyncWatch System Architecture and Dual Rule Compiler <a class="header-anchor" href="#syncwatch-system-architecture-and-dual-rule-compiler" aria-label="Permalink to “SyncWatch System Architecture and Dual Rule Compiler”">​</a></h1><p><code>SyncWatch</code> consists of a <strong>multi-channel normalizer for 8 global threat feeds</strong>, a <strong>5-stage SSRF guard</strong>, the <strong><code>WatchRuleCompilerService</code> dual compiler</strong>, and a <strong>self-sandbox verifier</strong> to safely ingest external threat intelligence and convert it into high-confidence audit and defense rules with zero false positives.</p><hr><h2 id="_1-six-threat-collection-channels-and-normalization-of-eight-global-threat-feeds" tabindex="-1">1. Six Threat Collection Channels and Normalization of Eight Global Threat Feeds <a class="header-anchor" href="#_1-six-threat-collection-channels-and-normalization-of-eight-global-threat-feeds" aria-label="Permalink to “1. Six Threat Collection Channels and Normalization of Eight Global Threat Feeds”">​</a></h2><p><code>SyncWatch</code> normalizes security intelligence from <strong>8 global threat feeds (OSV.dev, GitHub GHSA, NVD CVE, CISA KEV, Nuclei, OWASP CRS, MITRE ATT&amp;CK, KISA)</strong> across multiple formats (<code>REST_JSON</code>, <code>STIX_TAXII</code>, <code>YAML_NUCLEI</code>, <code>CRS_CONF</code>, <code>RSS_XML</code>, <code>DOCUMENT_UPLOAD</code>) into a single standard ledger (<code>watch_security_advisory</code>).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Collection Channel (<code>source_channel</code>)</th><th style="text-align:left;">Eight Core Providers (<code>provider_code</code>)</th><th style="text-align:left;">Ingestion Format</th><th style="text-align:left;">Key Normalized Extracted Fields</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Open-Source Ecosystem Advisories</strong></td><td style="text-align:left;"><code>OSV_DEV_FEED</code> (OSV.dev), <code>GITHUB_GHSA</code> (GitHub GHSA)</td><td style="text-align:left;"><code>REST_JSON</code></td><td style="text-align:left;">Vulnerable version ranges and patched versions per package across <code>MAVEN</code>, <code>NPM</code>, <code>PYPI</code>, <code>GO</code>, and <code>DOCKER</code></td></tr><tr><td style="text-align:left;"><strong>2. Global CVE Database</strong></td><td style="text-align:left;"><code>NVD_CVE_FEED</code> (NIST NVD CVE)</td><td style="text-align:left;"><code>REST_JSON</code></td><td style="text-align:left;">CVE ID, CVSS v3.1 score, CWE code, and affected CPE/package version ranges</td></tr><tr><td style="text-align:left;"><strong>3. Actively Exploited Vulnerabilities</strong></td><td style="text-align:left;"><code>CISA_KEV_CATALOG</code> (CISA KEV)</td><td style="text-align:left;"><code>REST_JSON</code></td><td style="text-align:left;">Vulnerabilities under active exploitation (<code>ACTIVE_EXPLOIT</code>), mandatory remediation deadlines, and mitigation guidance</td></tr><tr><td style="text-align:left;"><strong>4. Penetration Testing &amp; Vulnerability Scanner Templates</strong></td><td style="text-align:left;"><code>NUCLEI_TEMPLATES</code> (Nuclei)</td><td style="text-align:left;"><code>YAML_NUCLEI</code></td><td style="text-align:left;">HTTP request methods and paths, attack payload probes, and matcher regular expressions</td></tr><tr><td style="text-align:left;"><strong>5. WAF &amp; Attack Tactics Matrix</strong></td><td style="text-align:left;"><code>OWASP_CRS_FEED</code> (OWASP CRS), <code>MITRE_ATTACK_STIX</code> (MITRE ATT&amp;CK)</td><td style="text-align:left;"><code>CRS_CONF</code> / <code>STIX_TAXII</code></td><td style="text-align:left;">SQLi/XSS/RCE/LFI detection regexes, target locations (<code>HEADER</code>, <code>URI</code>, <code>QUERY</code>, <code>BODY</code>), grammar fingerprints, and MITRE tactic codes (such as <code>T1190</code>)</td></tr><tr><td style="text-align:left;"><strong>6. Domestic Security Advisories &amp; Diagnostic Documents</strong></td><td style="text-align:left;"><code>KISA_BOHO_NOTICE</code> (KISA Boho), Internal Diagnostic Uploads</td><td style="text-align:left;"><code>RSS_XML</code> / <code>DOC</code></td><td style="text-align:left;">KISA security notices and parsing/normalization of external penetration test reports (PDF/Markdown)</td></tr></tbody></table><hr><h2 id="_2-5-stage-ssrf-defense-guard" tabindex="-1">2. 5-Stage SSRF Defense Guard <a class="header-anchor" href="#_2-5-stage-ssrf-defense-guard" aria-label="Permalink to “2. 5-Stage SSRF Defense Guard”">​</a></h2><p>To prevent external feed URL synchronization or webhook-based advisory ingestion from being exploited for Server-Side Request Forgery (SSRF) against internal networks, every outbound collection request from <code>SyncWatch</code> must pass the <strong>5-Stage SSRF Defense Guard</strong>.</p>',9)),(t(),d(g,null,{default:o(()=>[s(i,{id:"mermaid-124",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Req%5B%22External%20Feed%20Sync%20Request%20(feed_url)%22%5D%20--%3E%20S1%5B%22Stage%201%3A%20Protocol%20and%20Port%20Validation%20(HTTPS%20Only%2C%20Block%20Non-Standard%20Ports)%22%5D%0A%20%20%20%20S1%20--%3E%20S2%5B%22Stage%202%3A%20Hostname%20Whitelist%20and%20Literal%20IP%20Validation%22%5D%0A%20%20%20%20S2%20--%3E%20S3%5B%22Stage%203%3A%20DNS%20Resolution%20and%20Private%2C%20Loopback%2C%20and%20Metadata%20Range%20Blocking%22%5D%0A%20%20%20%20S3%20--%3E%20S4%5B%22Stage%204%3A%20Disable%20HTTP%20Redirects%20(or%20Per-Hop%20Re-validation)%22%5D%0A%20%20%20%20S4%20--%3E%20S5%5B%22Stage%205%3A%20Response%20Stream%20Size%20Limit%20(Max%20Bytes)%20and%20Strict%20Timeout%22%5D%0A%20%20%20%20S5%20--%3E%20Norm%5B%22Normalization%20Parser%20(Load%20into%20watch_security_advisory)%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<ol><li><strong>Stage 1 — Scheme and Port Enforcement</strong>: Only the <code>https://</code> scheme (default port 443) is permitted; non-standard schemes such as <code>file://</code>, <code>gopher://</code>, <code>ftp://</code>, and <code>ldap://</code> are blocked immediately.</li><li><strong>Stage 2 — Registered Provider Domain Validation</strong>: Verifies that the target domain is a registered and approved provider in <code>watch_feed_source</code>, and rejects embedded user credentials (<code>user:pass@host</code>) in URLs.</li><li><strong>Stage 3 — DNS Rebinding and Private Range Blocking</strong>: Resolves DNS immediately prior to socket connection and rejects connections if the resolved IP falls within loopback (<code>127.0.0.0/8</code>, <code>::1</code>), private networks (<code>10.0.0.0/8</code>, <code>172.16.0.0/12</code>, <code>192.168.0.0/16</code>), link-local, or cloud metadata (<code>169.254.169.254</code>) ranges.</li><li><strong>Stage 4 — Redirect (<code>3xx</code>) Chain Control</strong>: Disables automatic redirects—or re-executes Stages 1 through 3 on every target URL—to prevent internal network bypass via open redirects.</li><li><strong>Stage 5 — Payload Bomb Protection</strong>: Enforces response <code>Content-Type</code> validation, a maximum received byte limit (e.g., 10 MB), and strict read timeouts to prevent Out-Of-Memory (OOM) exhaustion.</li></ol><hr><h2 id="_3-watchrulecompilerservice-dual-rule-compilation-and-self-sandbox-verification" tabindex="-1">3. <code>WatchRuleCompilerService</code> Dual Rule Compilation and Self-Sandbox Verification <a class="header-anchor" href="#_3-watchrulecompilerservice-dual-rule-compilation-and-self-sandbox-verification" aria-label="Permalink to “3. WatchRuleCompilerService Dual Rule Compilation and Self-Sandbox Verification”">​</a></h2><p>Once a normalized security advisory (<code>watch_security_advisory</code>) is stored, <code>WatchRuleCompilerService</code> analyzes it and simultaneously compiles it into two actionable types of security rules.</p><h3 id="_3-1-dual-compilation-artifacts" tabindex="-1">3.1 Dual Compilation Artifacts <a class="header-anchor" href="#_3-1-dual-compilation-artifacts" aria-label="Permalink to “3.1 Dual Compilation Artifacts”">​</a></h3><ul><li><strong>Shift-Left Audit Rules (<code>watch_verse_audit_rule</code> → <code>VerseAuditPack</code>)</strong>: <ul><li><strong>SCA Dependency Rules (<code>SCA_DEPENDENCY</code>)</strong>: Specifies ecosystem (<code>MAVEN</code>, <code>NPM</code>, etc.), package coordinates (<code>package_name</code>), vulnerable version range (<code>vulnerable_version_range</code>), and safe patched version (<code>patched_version</code>).</li><li><strong>SAST Static Code Rules (<code>SAST_CODE</code>)</strong>: Includes regular expressions (<code>sast_pattern_regex</code>) to detect vulnerable API calls or unsafe deserialization and query construction in source code AST/lines, along with a remediation guide (<code>remediation_guide_md</code>).</li><li><strong>DAST Penetration Test Probes (<code>DAST_PENTEST</code>)</strong>: Generates HTTP method (<code>dast_probe_method</code>), path (<code>dast_probe_path</code>), and payload (<code>dast_probe_payload</code>) to verify vulnerability reproducibility in an isolated staging environment.</li></ul></li><li><strong>Shift-Right Defense Rules (<code>watch_apim_defense_rule</code> → <code>ApimDefensePack</code>)</strong>: <ul><li><strong>Grammar Token Fingerprints (<code>grammar_fingerprint</code>)</strong>: Maps SQLi/XSS lexical token sequence fingerprints extracted by <code>SqlXssLexicalTokenizer</code> (e.g., <code>s&amp;1</code>, <code>sUE</code>, <code>;k</code>, <code>x_script</code>).</li><li><strong>Location-Specific Precision Regex (<code>detection_regex</code> &amp; <code>target_locations</code>)</strong>: Specifies the target inspection locations among <code>HEADER</code>, <code>URI</code>, <code>QUERY</code>, and <code>BODY</code> along with the endpoint path pattern (<code>target_path</code>).</li><li><strong>Restricted SpEL Defense Expressions (<code>defense_expression</code>)</strong>: Evaluates composite conditions (combining headers, query parameters, and grammar fingerprints) inside a safe sandbox expression backed by <code>SimpleEvaluationContext</code>.</li></ul></li></ul><h3 id="_3-2-self-sandbox-verification" tabindex="-1">3.2 Self-Sandbox Verification <a class="header-anchor" href="#_3-2-self-sandbox-verification" aria-label="Permalink to “3.2 Self-Sandbox Verification”">​</a></h3><p>Every compiled <code>watch_apim_defense_rule</code> must pass the self-sandbox verifier before enterprise-wide dispatch:</p><ol><li><strong>Positive Samples Verification (<code>positive_samples_json</code>)</strong>: Injects actual attack vector samples to verify 100% detection (<code>tp_rate = 100.00</code>).</li><li><strong>Negative Samples Verification (<code>negative_samples_json</code>)</strong>: Injects legitimate business API request samples to verify zero false positives (<code>fp_rate = 0.00</code>).</li><li><strong>ReDoS Timeout Verification</strong>: Measures whether regex and SpEL evaluation completes within <code>0.5ms</code> per item; only rules that pass all checks are promoted to <code>sandbox_verified = true</code> and <code>dispatch_status = &#39;READY&#39;</code>.</li></ol>',9))])}const A=r(h,[["render",p]]);export{x as __pageData,A as default};
